/// date-picker: Due date with quick picks
private struct DatePickerExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var due = Date(timeIntervalSince1970: 1_793_750_400)
    private let today = Date(timeIntervalSince1970: 1_793_750_400)
    private let presets: [(label: String, days: Int)] = [
        ("Today", 0),
        ("Tomorrow", 1),
        ("In a week", 7),
        ("In two weeks", 14),
    ]

    private func date(plus days: Int) -> Date {
        Calendar.current.date(byAdding: .day, value: days, to: today) ?? today
    }

    private func shown(_ days: Int) -> String {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en-GB")
        formatter.dateFormat = "EEE, d MMM"
        return formatter.string(from: date(plus: days))
    }

    var body: some View {
        MonarchFormField("Due date", helper: "Type a date or pick one.") {
            VStack(alignment: .leading, spacing: theme.spacing.space2) {
                MonarchTextField(
                    "Due date",
                    text: .constant(""),
                    prompt: "DD/MM/YYYY",
                    labelVisibility: .hidden,
                    leading: { EmptyView() },
                    trailing: { MonarchIcon(systemName: "calendar", size: .sm).foregroundStyle(theme.colors.textMuted) }
                )
                ForEach(Array(presets.enumerated()), id: \.offset) { _, preset in
                    Button {
                        due = date(plus: preset.days)
                    } label: {
                        HStack {
                            Text(preset.label)
                            Spacer()
                            Text(shown(preset.days)).foregroundStyle(theme.colors.textMuted)
                        }
                        .monarchTextStyle(.body)
                        .monarchMinimumHitTarget()
                        .contentShape(Rectangle())
                    }
                    .buttonStyle(.plain)
                }
                Divider()
                MonarchMiniMonth(
                        selection: Binding(get: { due }, set: { due = $0 ?? due }),
                        minimumDate: today,
                        today: today
                    )
            }
        }
        .environment(\.locale, Locale(identifier: "en-GB"))
    }
}

