/// date-time-picker: Interview time with a time zone
private struct DateTimePickerExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var start = Date(timeIntervalSince1970: 1_794_321_000)
    private let earliest = Date(timeIntervalSince1970: 1_793_782_800)
    private static let iso: DateFormatter = {
        let formatter = DateFormatter()
        formatter.dateFormat = "yyyy-MM-dd'T'HH:mm"
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.timeZone = TimeZone(identifier: "UTC")
        return formatter
    }()

    private static func text(_ date: Date, _ format: String, _ locale: String) -> String {
        let formatter = DateFormatter()
        formatter.dateFormat = format
        formatter.locale = Locale(identifier: locale)
        formatter.timeZone = TimeZone(identifier: "UTC")
        return formatter.string(from: date)
    }

    var body: some View {
        MonarchFormField("Interview", helper: "Value: " + Self.iso.string(from: start)) {
            HStack(spacing: theme.spacing.space2) {
                MonarchPickerField(Self.text(start, "dd/MM/yyyy", "en-GB")) {
                    EmptyView()
                } control: {
                    DatePicker("Interview", selection: $start, in: earliest..., displayedComponents: .date)
                } trailing: {
                    HStack(spacing: theme.spacing.space2) {
                        Button { start = earliest } label: {
                            MonarchIcon(systemName: "xmark", size: .sm).frame(width: 32, height: 32).contentShape(Rectangle())
                        }
                        .buttonStyle(.plain)
                        .accessibilityLabel("Reset")
                        MonarchIcon(systemName: "calendar", size: .sm)
                    }
                }
                MonarchPickerField(Self.text(start, "HH:mm", "en-GB")) {
                    MonarchIcon(systemName: "clock", size: .sm)
                } control: {
                    DatePicker("Interview", selection: $start, in: earliest..., displayedComponents: .hourAndMinute)
                } trailing: {
                    EmptyView()
                }
                Text("IST").monarchTextStyle(.body).foregroundStyle(theme.colors.textMuted)
            }
            .environment(\.timeZone, TimeZone(identifier: "UTC") ?? .gmt)
            .environment(\.locale, Locale(identifier: "en-GB"))
        }
    }
}

