/// reschedule-dialog: Reschedule to an open slot
private struct RescheduleDialogExample0: View {
    private static let day = Date(timeIntervalSince1970: 1_793_836_800)

    @Environment(\.monarchTheme) private var theme
    @State private var isPresented = PreviewMode.presented ? true : false
    @State private var slot: Date?
    @State private var selectedDay: Date? = day
    @State private var reason = ""
    @State private var isSaving = false
    @State private var error: String?

    private var slots: [MonarchSlotPickerSlot] {
        [9, 9.5, 11, 14, 15.5].map { MonarchSlotPickerSlot(start: Self.day.addingTimeInterval($0 * 3_600)) }
    }

    private var newTime: Date? { slot ?? selectedDay }

    private func save() {
        guard newTime != nil else { return }
        isSaving = true
        error = nil
        Task {
            // Save the new time; on failure set error and keep every choice.
            isSaving = false
            isPresented = false
        }
    }

    var body: some View {
        VStack(alignment: .leading, spacing: theme.spacing.space2) {
            MonarchButton("Reschedule") { isPresented = true }
            Text("Not moved yet")
                .monarchTextStyle(.caption)
                .foregroundStyle(theme.colors.textMuted)
        }
        .monarchDialog(
            isPresented: $isPresented,
            title: "Reschedule",
            message: "Consultation with Sam Lee \u{00B7} Currently Wed, 4 Nov 2026, 09:30 GMT",
            showsCloseButton: true
        ) {
            VStack(alignment: .leading, spacing: theme.spacing.space4) {
                MonarchSlotPicker(selection: $slot, day: $selectedDay, slots: slots, timeZone: "Europe/London", today: Date(timeIntervalSince1970: 1_793_577_600))
                MonarchTextField("Reason (optional)", text: $reason, prompt: "", helper: "Kept in the history.", axis: .vertical, lineLimit: 3...6)
                .monarchHelperAbove()
                if let error {
                    MonarchInlineErrorRetry(error) { save() }
                }
            }
        } footer: {
            HStack(spacing: theme.spacing.space2) {
                MonarchButton("Cancel") { isPresented = false }
                    .disabled(isSaving)
                MonarchButton("Reschedule", variant: .primary, isLoading: isSaving) { save() }
                    .disabled(newTime == nil)
            }
        }
    }
}

/// slot-picker: Booking with a time zone picker
private struct SlotPickerExample0: View {
    @State private var selection: Date?
    @State private var day: Date? = Date(timeIntervalSince1970: 1_793_750_400)
    @State private var zone = "Europe/London"

    private var slots: [MonarchSlotPickerSlot] {
        guard let day else { return [] }
        let shift = day.timeIntervalSince(Date(timeIntervalSince1970: 1_793_750_400))
        return [
            MonarchSlotPickerSlot(start: Date(timeIntervalSince1970: 1_793_782_800).addingTimeInterval(shift)),
            MonarchSlotPickerSlot(start: Date(timeIntervalSince1970: 1_793_784_600).addingTimeInterval(shift)),
            MonarchSlotPickerSlot(start: Date(timeIntervalSince1970: 1_793_786_400).addingTimeInterval(shift), isDisabled: true),
            MonarchSlotPickerSlot(start: Date(timeIntervalSince1970: 1_793_788_200).addingTimeInterval(shift)),
            MonarchSlotPickerSlot(start: Date(timeIntervalSince1970: 1_793_790_000).addingTimeInterval(shift), seatsLeft: 3),
            MonarchSlotPickerSlot(start: Date(timeIntervalSince1970: 1_793_791_800).addingTimeInterval(shift)),
        ]
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            MonarchSlotPicker(
                selection: $selection,
                day: $day,
                slots: slots,
                timeZone: zone,
                minimumDate: Date(timeIntervalSince1970: 1_793_577_600),
                maximumDate: Date(timeIntervalSince1970: 1_798_675_200),
                today: Date(timeIntervalSince1970: 1_793_577_600),
                availableDays: [Date(timeIntervalSince1970: 1_793_750_400), Date(timeIntervalSince1970: 1_793_836_800), Date(timeIntervalSince1970: 1_793_923_200), Date(timeIntervalSince1970: 1_794_182_400), Date(timeIntervalSince1970: 1_794_268_800), Date(timeIntervalSince1970: 1_794_355_200)],
                businessTimeZone: "Europe/London",
                pinnedTimeZones: ["Europe/London", "America/New_York", "Asia/Kolkata"],
                onTimeZoneChange: { zone = $0 }
            )
            .environment(\.locale, Locale(identifier: "en-GB"))
            Text(verbatim: "Selected: " + (selection.map { $0.formatted(.iso8601) } ?? "none"))
                .monarchTextStyle(.caption)
        }
    }
}

/// time-grid: Work week
private struct TimeGridExample0: View {
    private var calendar: Calendar {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = TimeZone(identifier: "UTC") ?? .gmt
        calendar.firstWeekday = 2
        return calendar
    }
    private func hex(_ value: String) -> Color {
        let number = UInt32(value.drop(while: { $0 == "#" }), radix: 16) ?? 0
        return Color(
            red: Double((number >> 16) & 0xFF) / 255,
            green: Double((number >> 8) & 0xFF) / 255,
            blue: Double(number & 0xFF) / 255
        )
    }

    var body: some View {
        MonarchTimeGrid(
            days: [Date(timeIntervalSince1970: 1_793_577_600), Date(timeIntervalSince1970: 1_793_664_000), Date(timeIntervalSince1970: 1_793_750_400), Date(timeIntervalSince1970: 1_793_836_800), Date(timeIntervalSince1970: 1_793_923_200)],
            events: [
                MonarchAgendaEvent("Conference", id: "t1", start: Date(timeIntervalSince1970: 1_793_664_000), end: Date(timeIntervalSince1970: 1_793_750_400), isAllDay: true, color: hex("#ca8a04")),
                MonarchAgendaEvent("Stand-up", id: "t2", start: Date(timeIntervalSince1970: 1_793_610_000), end: Date(timeIntervalSince1970: 1_793_610_900), color: hex("#0f766e")),
                MonarchAgendaEvent("Design review", id: "t3", start: Date(timeIntervalSince1970: 1_793_784_600), end: Date(timeIntervalSince1970: 1_793_790_000), detail: "Room 4", color: hex("#7c3aed")),
                MonarchAgendaEvent("Interview", id: "t4", start: Date(timeIntervalSince1970: 1_793_786_400), end: Date(timeIntervalSince1970: 1_793_790_000), color: hex("#0891b2"), status: .tentative),
                MonarchAgendaEvent("Lunch & learn", id: "t5", start: Date(timeIntervalSince1970: 1_793_880_000), end: Date(timeIntervalSince1970: 1_793_883_600), color: hex("#2563eb")),
                MonarchAgendaEvent("Retrospective", id: "t6", start: Date(timeIntervalSince1970: 1_793_977_200), end: Date(timeIntervalSince1970: 1_793_980_800), color: hex("#c2410c"), status: .cancelled),
                MonarchAgendaEvent("Planning", id: "t7", start: Date(timeIntervalSince1970: 1_793_714_400), end: Date(timeIntervalSince1970: 1_793_719_800), color: hex("#db2777")),
            ],
            now: Date(timeIntervalSince1970: 1_793_788_800),
            workingHours: [1, 2, 3, 4, 5].flatMap { weekday in
                [
                    MonarchTimeGridWorkingHours(weekday: weekday, start: 540, end: 720),
                    MonarchTimeGridWorkingHours(weekday: weekday, start: 780, end: 1080),
                ]
            },
            unavailable: [
                MonarchTimeGridUnavailable(id: "off", start: Date(timeIntervalSince1970: 1_793_955_600), end: Date(timeIntervalSince1970: 1_793_966_400), label: "Time off"),
            ],
            scrollToMinutes: 480,
            showsAllDayRow: true,
            calendar: calendar
        )
        .environment(\.locale, Locale(identifier: "en-GB"))
        .frame(height: 416)
    }
